import sys

data = sys.stdin.read().split()
p = 0
m = int(data[p]); p += 1
raw = []
for _ in range(m):
    price = int(data[p]); c = int(data[p + 1])
    raw.append((price, data[p + 2:p + 2 + c]))
    p += 2 + c
q = int(data[p])
order = data[p + 1:p + 1 + q]
idx = {x: i for i, x in enumerate(order)}
best = {}
for price, items in raw:
    mask = 0
    for it in items:
        if it in idx:
            mask |= 1 << idx[it]
    if mask and (mask not in best or price < best[mask]):
        best[mask] = price
full = (1 << q) - 1
INF = float('inf')
dp = [INF] * (full + 1)
dp[0] = 0
opts = list(best.items())
for mask in range(full + 1):
    d = dp[mask]
    if d == INF:
        continue
    for em, pr in opts:
        nm = mask | em
        if d + pr < dp[nm]:
            dp[nm] = d + pr
print(dp[full] if dp[full] != INF else -1)

